-- Preview pending intent only if it is an actual eligible price/stock target.
create function operations_private.hub_reconcile_pending_eligible_v1(p_queue jsonb)
returns boolean language plpgsql stable set search_path=pg_catalog as $$
declare target jsonb; part text; v numeric;
begin
 if p_queue->>'field_key'='sellpia_current_stock' then
  if jsonb_typeof(p_queue->'after_value') is distinct from 'number' then return false;end if;
  v:=(p_queue->>'after_value')::numeric;return v>=0 and v=trunc(v) and v<=9007199254740991;
 end if;
 target:=jsonb_build_object('base',p_queue->'price_base_after','discounted',p_queue->'price_discounted_base_after','option',p_queue->'price_option_after','final',p_queue->'price_final_after','terms',coalesce(p_queue->'price_discount_terms_after','[]'));
 foreach part in array array['base','discounted','option','final'] loop
  if jsonb_typeof(target->part) is distinct from 'number' then return false;end if;
  v:=(target->>part)::numeric;if v<>trunc(v) or abs(v)>9007199254740991 or part<>'option' and v<0 then return false;end if;
 end loop;
 if (target->>'discounted')::numeric+(target->>'option')::numeric<>(target->>'final')::numeric then return false;end if;
 if p_queue->>'base_price_source'='manual' or p_queue->>'option_price_source'='manual' or p_queue->>'pricing_input_mode'='final' or p_queue->>'base_price_source'='discount' and exists(select 1 from jsonb_array_elements(coalesce(p_queue->'price_discount_terms_after','[]')) t where t->>'input_source'='manual') then return true;end if;
 return exists(select 1 from operations_private.hub_calculated_results c where c.sku=p_queue->>'sellpia_sku_code' and c.scope=p_queue->>'source_channel' and c.field='platform_final_price' and c.status='calculated' and c.error is null
  and c.value=(target->>'final')::numeric and coalesce(c.result_details->'discount_terms','[]')=target->'terms'
  and coalesce(c.result_details->>'input_fingerprint','')<>'' and c.result_details->>'input_fingerprint'=operations_private.hub_input_fingerprint_v1(c.sku,c.scope)
  and exists(select 1 from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id where a.sku=c.sku and a.scope=c.scope and r.is_active and a.target_field like 'platform_%')
  and not exists(select 1 from (values ('platform_registration_price','base'),('platform_discount_price','discounted'),('platform_option_price','option')) f(field,key) where not exists(select 1 from operations_private.hub_calculated_results r where r.sku=c.sku and r.scope=c.scope and r.field=f.field and r.status='calculated' and r.error is null and r.generation_id=c.generation_id and r.value=(target->>f.key)::numeric)));
end $$;
revoke all on function operations_private.hub_reconcile_pending_eligible_v1(jsonb) from public,anon,authenticated;


CREATE OR REPLACE FUNCTION operations_private.hub_baseline_reconcile_page_v1(p_session_token text, p_source text, p_snapshot_id uuid, p_expected_version_id uuid, p_after text, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET statement_timeout TO '30s'
AS $function$
declare result jsonb; current_id uuid;
begin
 perform operations_private.require_operations_hub_operator_session(p_session_token);
 if p_source is null or p_source not in ('smartstore','makeshop','ably') or p_limit is null or p_limit not between 1 and 200 or length(coalesce(p_after,''))>512 then raise exception 'invalid reconcile scope';end if;
 select current_version_id into current_id from operations_private.hub_baseline_heads where source=p_source;
 if current_id is null or p_expected_version_id is null and p_after is not null or p_expected_version_id is not null and current_id is distinct from p_expected_version_id then raise exception 'stale baseline head';end if;
 if not exists(select 1 from public.seller_inventory_snapshots where snapshot_id=p_snapshot_id and source_channel=p_source and upload_status='ready') then raise exception 'invalid seller snapshot';end if;
 with baseline as (select jsonb_build_array(b.product_code,b.option_code)::text identity,b.product_code,b.option_code,b.facts from operations_private.hub_baseline_rows b where b.version_id=current_id), pairs as (
  select coalesce(n.identity,b.identity) identity,coalesce(n.product_code,b.product_code) product_code,coalesce(n.option_code,b.option_code) option_code,b.facts baseline,n.facts seller from operations_private.hub_snapshot_facts_v1(p_source,p_snapshot_id) n full join baseline b using(identity)
 ), bounded as (select * from pairs where p_after is null or identity>p_after order by identity limit p_limit)
 select coalesce(jsonb_agg(to_jsonb(b)||jsonb_build_object('pending',coalesce((select jsonb_agg((to_jsonb(q)-'created_at'-'updated_at')||jsonb_build_object('target_eligible',operations_private.hub_reconcile_pending_eligible_v1(to_jsonb(q))) order by q.field_key) from (select distinct on (field_key) * from public.operations_hub_change_queue where source_channel=p_source and seller_product_code=b.product_code and coalesce(seller_option_code,'')=b.option_code and status in ('pending','validated','processing') and field_key in ('sellpia_sale_price','sellpia_current_stock') order by field_key,updated_at desc,change_id desc) q),'[]')) order by b.identity),'[]') into result from bounded b;
 return jsonb_build_object('source',p_source,'version_id',current_id,'snapshot_id',p_snapshot_id,'rows',result,'next_after',case when jsonb_array_length(result)=p_limit then result->-1->>'identity' end,'preview_only',true);
end $function$
;notify pgrst,'reload schema';
